  "animated-sliding-button": "const EXPAND_MS = 340;\nconst PARK_MS = 260;\n\nconst canHover = () =>\n  window.matchMedia(\"(hover: hover) and (pointer: fine)\").matches;\n\nconst prefersReducedMotion = () =>\n  window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n\nconst timers = new WeakMap();\nconst dirs = new WeakMap();\n\nconst clearTimer = (btn) => {\n  const id = timers.get(btn);\n  if (id) window.clearTimeout(id);\n  timers.delete(btn);\n};\n\nconst wait = (btn, ms, fn) => {\n  clearTimer(btn);\n  timers.set(\n    btn,\n    window.setTimeout(() => {\n      timers.delete(btn);\n      fn();\n    }, ms),\n  );\n};\n\nconst isOn = (btn) => {\n  if (btn.disabled) return false;\n  return btn.matches(\":focus-visible\") || (canHover() && btn.matches(\":hover\"));\n};\n\nconst step = (btn) => {\n  const on = isOn(btn);\n  const state = btn.dataset.iconState || \"idle\";\n  const dir = dirs.get(btn);\n\n  if (prefersReducedMotion()) {\n    clearTimer(btn);\n    btn.dataset.iconState = on ? \"park\" : \"idle\";\n    return;\n  }\n\n  if (on) {\n    if (state === \"park\") return;\n    if (state === \"idle\") {\n      btn.dataset.iconState = \"expand\";\n      dirs.set(btn, \"in\");\n      wait(btn, EXPAND_MS, () => step(btn));\n      return;\n    }\n    if (dir === \"in\" && timers.has(btn)) return;\n    clearTimer(btn);\n    btn.dataset.iconState = \"park\";\n    dirs.set(btn, \"in\");\n    return;\n  }\n\n  if (state === \"idle\") return;\n  if (state === \"park\") {\n    btn.dataset.iconState = \"expand\";\n    dirs.set(btn, \"out\");\n    wait(btn, PARK_MS, () => step(btn));\n    return;\n  }\n  if (dir === \"out\" && timers.has(btn)) return;\n  clearTimer(btn);\n  btn.dataset.iconState = \"idle\";\n  dirs.set(btn, \"out\");\n};\n\nconst bind = (btn) => {\n  const sync = () => step(btn);\n  btn.addEventListener(\"pointerenter\", sync);\n  btn.addEventListener(\"pointerleave\", sync);\n  btn.addEventListener(\"focus\", sync);\n  btn.addEventListener(\"blur\", sync);\n};\n\nconst buttonIconSlide = {\n  init() {\n    document.querySelectorAll(\"[data-btn-icon-slide]\").forEach(bind);\n  },\n};\n\ndocument.addEventListener(\"DOMContentLoaded\", () => {\n  buttonIconSlide.init();\n});\n",
  "sliding-tab-on-hover": "const prefersReducedMotion = () =>\n  window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n\nconst getBouncyEase = () => {\n  if (typeof CustomEase === \"undefined\") return \"power2.out\";\n  gsap.registerPlugin(CustomEase);\n  CustomEase.create(\"bouncy-ease\", \"0.34, 1.42, 0.64, 1\");\n  return \"bouncy-ease\";\n};\n\nconst getItemBounds = (item) => {\n  const { offsetLeft: left, offsetTop: top, offsetWidth: width, offsetHeight: height } = item;\n  return { left, top, width, height };\n};\n\nconst bindNavTabs = (nav) => {\n  if (nav.dataset.navTabsReady) return;\n  nav.dataset.navTabsReady = \"true\";\n\n  const indicator = nav.querySelector(\"[data-nav-indicator]\");\n  const items = [...nav.querySelectorAll(\"[data-nav-item]\")];\n  if (!indicator || !items.length) return;\n\n  const bouncyEase = getBouncyEase();\n  let isVisible = false;\n\n  gsap.set(indicator, { opacity: 0, scale: 0, transformOrigin: \"center center\" });\n\n  const getActiveItem = () => items.find((item) => item.dataset.active === \"true\") ?? null;\n\n  const revealAtItem = (item) => {\n    const bounds = getItemBounds(item);\n    if (prefersReducedMotion()) {\n      gsap.set(indicator, { ...bounds, opacity: 1, scale: 1 });\n      isVisible = true;\n      return;\n    }\n    gsap.set(indicator, { ...bounds, opacity: 1, scale: 0 });\n    gsap.to(indicator, { scale: 1, duration: 0.6, ease: bouncyEase, overwrite: \"auto\" });\n    isVisible = true;\n  };\n\n  const moveToItem = (item) => {\n    if (!isVisible) {\n      revealAtItem(item);\n      return;\n    }\n    if (prefersReducedMotion()) {\n      gsap.set(indicator, { ...getItemBounds(item), opacity: 1, scale: 1 });\n      return;\n    }\n    gsap.to(indicator, {\n      ...getItemBounds(item),\n      opacity: 1,\n      scale: 1,\n      duration: 0.35,\n      ease: \"power2.out\",\n      overwrite: \"auto\",\n    });\n  };\n\n  const hideIndicator = () => {\n    const activeItem = getActiveItem();\n    if (activeItem) {\n      moveToItem(activeItem);\n      return;\n    }\n    if (prefersReducedMotion()) {\n      gsap.set(indicator, { opacity: 0, scale: 0 });\n      isVisible = false;\n      return;\n    }\n    gsap.to(indicator, {\n      opacity: 0,\n      scale: 0,\n      duration: 0.25,\n      ease: \"power2.in\",\n      overwrite: \"auto\",\n      onComplete: () => {\n        isVisible = false;\n      },\n    });\n  };\n\n  const resetIndicator = () => {\n    const activeItem = getActiveItem();\n    if (activeItem) {\n      gsap.set(indicator, { ...getItemBounds(activeItem), opacity: 1, scale: 1 });\n      isVisible = true;\n      return;\n    }\n    gsap.set(indicator, { opacity: 0, scale: 0 });\n    isVisible = false;\n  };\n\n  const activeItem = getActiveItem();\n  if (activeItem) {\n    requestAnimationFrame(() => revealAtItem(activeItem));\n  }\n\n  nav.addEventListener(\"pointerover\", (event) => {\n    const item = event.target.closest(\"[data-nav-item]\");\n    if (item && nav.contains(item)) moveToItem(item);\n  });\n\n  nav.addEventListener(\"pointerleave\", hideIndicator);\n\n  nav.addEventListener(\"focusin\", (event) => {\n    const item = event.target.closest(\"[data-nav-item]\");\n    if (item && nav.contains(item)) moveToItem(item);\n  });\n\n  nav.addEventListener(\"focusout\", (event) => {\n    if (!nav.contains(event.relatedTarget)) hideIndicator();\n  });\n\n  items.forEach((item) => {\n    item.addEventListener(\"click\", () => {\n      items.forEach((el) => {\n        const isActive = el === item;\n        el.dataset.active = isActive ? \"true\" : \"false\";\n        if (isActive) el.setAttribute(\"aria-current\", el.tagName === \"A\" ? \"page\" : \"true\");\n        else el.removeAttribute(\"aria-current\");\n      });\n    });\n  });\n\n  window.addEventListener(\"resize\", resetIndicator);\n};\n\nconst slidingTabOnHover = {\n  init(root = document) {\n    if (typeof gsap === \"undefined\") return;\n    root.querySelectorAll(\"[data-nav-tabs]\").forEach(bindNavTabs);\n  },\n};\n\nif (document.readyState === \"loading\") {\n  document.addEventListener(\"DOMContentLoaded\", () => slidingTabOnHover.init());\n} else {\n  slidingTabOnHover.init();\n}\n"
